import { useState, useEffect, useRef } from "react";

function dataURLtoBlob(dataurl) {
  const arr = dataurl.split(",");
  const mime = arr[0].match(/:(.*?);/)[1];
  const bstr = atob(arr[1]);
  let n = bstr.length;
  const u8arr = new Uint8Array(n);
  while (n--) {
    u8arr[n] = bstr.charCodeAt(n);
  }
  return new Blob([u8arr], { type: mime });
}
const CameraTest = ({ onCapture }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function startCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "environment" },
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Failed to access camera: " + err.message);
      }
    }
    startCamera();
    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        videoRef.current.srcObject.getTracks().forEach((track) => track.stop());
      }
    };
  }, []);

  // const capturePhoto = () => {
  //   if (videoRef.current && canvasRef.current) {
  //     const video = videoRef.current;
  //     const canvas = canvasRef.current;
  //     canvas.width = video.videoWidth;
  //     canvas.height = video.videoHeight;
  //     canvas.getContext("2d").drawImage(video, 0, 0);
  //     const photoData = canvas.toDataURL("image/jpeg");
  //     if (onCapture) {
  //       onCapture(photoData);
  //     }
  //     video.srcObject.getTracks().forEach((track) => track.stop());
  //   }
  // };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      canvas.getContext("2d").drawImage(video, 0, 0);
      const photoData = canvas.toDataURL("image/jpeg");
      // Convert data URL to Blob
      const photoBlob = dataURLtoBlob(photoData);
      // If you need a File object:
      // const file = new File([photoBlob], `capture-${Date.now()}.jpg`, { type: "image/jpeg" });
      if (onCapture) {
        onCapture(photoBlob); // or onCapture(file)
      }
      video.srcObject.getTracks().forEach((track) => track.stop());
    }
  };

  return (
    <div className="flex flex-col items-center p-4 bg-gray-100 min-h-screen">
      <h1 className="text-2xl font-bold mb-4">Camera Access</h1>
      {error && <div className="text-red-500 mb-4">{error}</div>}
      <video
        ref={videoRef}
        autoPlay
        className="w-full max-w-md rounded-lg shadow-lg"
      ></video>
      <button
        onClick={capturePhoto}
        className="mt-4 px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
      >
        Capture Photo
      </button>
      <canvas ref={canvasRef} className="hidden"></canvas>
    </div>
  );
};
export default CameraTest;
